import { _decorator, Button, Toggle } from 'cc';
import { PopupBase } from './PopupBase';
import { VirtualList } from '../VirtualList';
import { TableListModel } from '../../runtime/TableList/TableListModel';
import { TableListViewModel } from '../../runtime/TableList/TableListViewModel';
import type { TableListEntry } from '../../runtime/TableList/TableListViewModel';
import { TableListSelection } from '../../runtime/TableList/TableListSelection';
import { TableSeatState } from '../../runtime/TableList/TableListTypes';

const { ccclass, property } = _decorator;

/**
 * SeatLobbyPopup — 遊戲內「SAET LOBBY 選擇座位」彈窗。
 *
 * 資料／選取這條資料流完全沿用既有大廳選桌那一套：
 * TableListModel（存資料+發事件）→ TableListViewModel（join+篩選+快取）
 * → VirtualList（渲染）＋ TableListSelection（模組級單例，記錄目前選中哪一桌）。
 * 「入座」動作沿用既有 TableListDetailPanel 的 runGameScene() 行為，跟大廳選桌
 * 完全一致（任務對話已確認）——TableListDetailPanel 是獨立元件，掛在這個彈窗
 * prefab 底下當子節點即可，靠 TableListSelection 事件自己同步，這裡不用另外接。
 *
 * SlotApi 協定目前沒有桌位清單相關訊息類型（同 TableListSceneController 檔頭
 * 說明），先用 seedFakeData() 塞假資料撐起整條資料流，之後接上真實協定時只需要
 * 把 seedFakeData() 換成真正的 API 呼叫（改呼叫 model.upsertIdentities()/
 * upsertStats()），TableListViewModel/VirtualList/TableListDetailPanel 完全不用動。
 *
 * 「保留」（拆圖備注裡跟「入座」分開的按鈕）目前沒有對應後端協定，比照
 * TableStats.raw 的作法先不假設形狀，只開放 onReserve 回呼給呼叫端自己決定
 * 行為，這裡不做任何預設動作。
 */
@ccclass('1002/SeatLobbyPopup')
export class SeatLobbyPopup extends PopupBase {
    @property(VirtualList)
    protected virtualList: VirtualList<TableListEntry> = null!;

    @property({ type: Toggle, tooltip: '「顯示座位」篩選開關：開＝只顯示空位，關＝全部顯示' })
    protected emptyOnlyToggle: Toggle | null = null;

    @property({ type: Button, tooltip: '選配：拆圖規格裡跟「入座」分開的「保留」按鈕，沒有就留空' })
    protected reserveButton: Button | null = null;

    @property({ tooltip: '假桌位筆數（後端協定確認前的暫時測試資料，同 TableListSceneController）' })
    protected fakeTableCount: number = 100;

    /** 按下「保留」時呼叫目前選中的桌位；沒有對應後端協定前純粹回呼給呼叫端自己決定行為 */
    public onReserve: ((entry: TableListEntry) => void) | null = null;

    private readonly model = new TableListModel();
    private viewModel: TableListViewModel | null = null;
    private entries: TableListEntry[] = [];

    protected override onLoad(): void {
        super.onLoad();

        this.viewModel = new TableListViewModel(this.model);
        this.subscribeEvent(this.viewModel.events, 'entriesChanged', ({ entries }) => {
            this.entries = entries;
            this.virtualList.setData(entries);
        });
        this.subscribeEvent(TableListSelection.events, 'selectedChanged', ({ entry }) => this.scrollToSelected(entry));

        if (this.emptyOnlyToggle) {
            this.emptyOnlyToggle.node.on(Toggle.EventType.TOGGLE, this.onFilterToggle, this);
            this.trackDisposer(() => {
                if (this.emptyOnlyToggle?.node?.isValid) this.emptyOnlyToggle!.node.off(Toggle.EventType.TOGGLE, this.onFilterToggle, this);
            });
        }
        if (this.reserveButton) {
            this.reserveButton.node.on(Button.EventType.CLICK, this.onReserveClick, this);
            this.trackDisposer(() => {
                if (this.reserveButton?.node?.isValid) this.reserveButton!.node.off(Button.EventType.CLICK, this.onReserveClick, this);
            });
        }

        this.seedFakeData();
    }

    public override onDestroy(): void {
        super.onDestroy();
        this.viewModel?.dispose();
        // 避免下次打開選座位彈窗殘留上次選中的桌位
        TableListSelection.clear();
    }

    private onFilterToggle(): void {
        this.viewModel?.setFilter(this.emptyOnlyToggle!.isChecked ? 'empty' : 'all');
    }

    private onReserveClick(): void {
        const entry = TableListSelection.getSelected();
        if (entry) this.onReserve?.(entry);
    }

    /** 選中的桌位不在目前可視範圍時，捲動列表讓它進來（同 TableListSceneController） */
    private scrollToSelected(entry: TableListEntry | null): void {
        if (!entry) return;
        const index = this.entries.findIndex((e) => e.identity.tableId === entry.identity.tableId);
        if (index < 0) return;
        this.virtualList.scrollToIndex(index);
    }

    /** 暫時假資料，同 TableListSceneController.seedFakeData()，見檔頭說明 */
    private seedFakeData(): void {
        const tables = Array.from({ length: this.fakeTableCount }, (_, i) => ({
            tableId: String(i + 1),
            gameCode: 'sethg',
            seatState: Math.random() < 0.5 ? TableSeatState.Empty : TableSeatState.Full,
        }));
        this.model.upsertIdentities(tables);
    }
}
